     1	<!DOCTYPE html>
     2	<html lang="en">
     3	<head>
     4	<meta charset="utf-8">
     5	<meta name="viewport" content="width=device-width, initial-scale=1">
     6	<title>Todos</title>
     7	<style>
     8	  * { box-sizing: border-box; }
     9	  body {
    10	    margin: 0;
    11	    padding: 40px 16px;
    12	    font: 16px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
    13	    background: #f5f5f4;
    14	    color: #1c1917;
    15	  }
    16	  main { max-width: 520px; margin: 0 auto; }
    17	  h1 { font-size: 28px; margin: 0 0 16px; }
    18	  form { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 16px; }
    19	  input[type="text"] {
    20	    flex: 1;
    21	    min-width: 0;
    22	    padding: 10px 12px;
    23	    font: inherit;
    24	    border: 1px solid #d6d3d1;
    25	    border-radius: 8px;
    26	    background: #fff;
    27	  }
    28	  input[type="date"], select {
    29	    padding: 10px 12px;
    30	    font: inherit;
    31	    border: 1px solid #d6d3d1;
    32	    border-radius: 8px;
    33	    background: #fff;
    34	    color: inherit;
    35	  }
    36	  .search { display: block; width: 100%; margin-bottom: 12px; padding: 10px 12px; font: inherit; border: 1px solid #d6d3d1; border-radius: 8px; background: #fff; }
    37	  .edit { flex: 1; min-width: 0; padding: 4px 8px; font: inherit; border: 1px solid #d6d3d1; border-radius: 6px; }
    38	  input[type="text"]:focus, input[type="date"]:focus, select:focus, .search:focus, .edit:focus { outline: 2px solid #2563eb; outline-offset: -1px; border-color: transparent; }
    39	  button {
    40	    font: inherit;
    41	    border: 0;
    42	    border-radius: 8px;
    43	    cursor: pointer;
    44	  }
    45	  .add { padding: 10px 18px; background: #2563eb; color: #fff; }
    46	  .add:hover { background: #1d4ed8; }
    47	  ul { list-style: none; margin: 0; padding: 0; }
    48	  li {
    49	    display: flex;
    50	    align-items: center;
    51	    gap: 12px;
    52	    padding: 10px 12px;
    53	    margin-bottom: 8px;
    54	    background: #fff;
    55	    border: 1px solid #e7e5e4;
    56	    border-radius: 8px;
    57	  }
    58	  .text { flex: 1; overflow-wrap: anywhere; }
    59	  li input[type="checkbox"] { width: 18px; height: 18px; margin: 0; cursor: pointer; accent-color: #2563eb; }
    60	  li[data-completed="true"] .text { color: #a8a29e; text-decoration: line-through; }
    61	  .due { font-size: 14px; color: #57534e; white-space: nowrap; }
    62	  /* Priority is shown as a neutral text label only; no colour coding. */
    63	  .priority { font-size: 12px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.04em; padding: 2px 6px; border-radius: 4px; white-space: nowrap; background: #f5f5f4; color: #57534e; }
    64	  li[data-overdue="true"] { border-color: #f87171; }
    65	  li[data-overdue="true"] .due { color: #b91c1c; font-weight: 600; }
    66	  .filters { display: flex; gap: 8px; margin-bottom: 16px; }
    67	  .filters button { padding: 6px 12px; background: transparent; color: #44403c; border: 1px solid #d6d3d1; }
    68	  .filters button:hover { background: #e7e5e4; }
    69	  .filters button[aria-pressed="true"] { background: #1c1917; color: #fff; border-color: #1c1917; }
    70	  .bulk { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 16px; }
    71	  .bulk button { padding: 6px 12px; background: transparent; color: #44403c; border: 1px solid #d6d3d1; }
    72	  .bulk button:hover { background: #e7e5e4; }
    73	  .delete { padding: 6px 10px; background: transparent; color: #b91c1c; }
    74	  .delete:hover { background: #fee2e2; }
    75	  .empty { color: #78716c; text-align: center; padding: 16px 0; }
    76	</style>
    77	</head>
    78	<body>
    79	<main>
    80	  <h1>Todos</h1>
    81	  <form id="todo-form">
    82	    <input type="text" data-testid="todo-input" placeholder="What needs doing?" aria-label="New todo" autocomplete="off">
    83	    <input type="date" data-testid="todo-due" aria-label="Due date (optional)">
    84	    <select data-testid="todo-priority" aria-label="Priority">
    85	      <option value="low">Low</option>
    86	      <option value="med" selected>Med</option>
    87	      <option value="high">High</option>
    88	    </select>
    89	    <button type="submit" class="add" data-testid="todo-add">Add</button>
    90	  </form>
    91	  <input type="search" class="search" data-testid="search-input" placeholder="Search todos" aria-label="Search todos" autocomplete="off">
    92	  <div class="filters" role="group" aria-label="Filter todos">
    93	    <button type="button" data-testid="filter-all" data-filter="all" aria-pressed="true">All</button>
    94	    <button type="button" data-testid="filter-active" data-filter="active" aria-pressed="false">Active</button>
    95	    <button type="button" data-testid="filter-completed" data-filter="completed" aria-pressed="false">Completed</button>
    96	  </div>
    97	  <div class="bulk" role="group" aria-label="Bulk actions">
    98	    <button type="button" data-testid="bulk-mark-all">Mark all complete</button>
    99	    <button type="button" data-testid="bulk-clear-completed">Clear completed</button>
   100	  </div>
   101	  <ul data-testid="todo-list"></ul>
   102	  <p class="empty" hidden>No todos yet.</p>
   103	</main>
   104	<script>
   105	(function () {
   106	  var STORAGE_KEY = 'todos';
   107	  var form = document.getElementById('todo-form');
   108	  var input = document.querySelector('[data-testid="todo-input"]');
   109	  var dueInput = document.querySelector('[data-testid="todo-due"]');
   110	  var priorityInput = document.querySelector('[data-testid="todo-priority"]');
   111	  var list = document.querySelector('[data-testid="todo-list"]');
   112	  var empty = document.querySelector('.empty');
   113	  var filterButtons = document.querySelectorAll('[data-filter]');
   114	  var searchInput = document.querySelector('[data-testid="search-input"]');
   115	  var markAllButton = document.querySelector('[data-testid="bulk-mark-all"]');
   116	  var clearCompletedButton = document.querySelector('[data-testid="bulk-clear-completed"]');
   117	
   118	  var PRIORITIES = ['low', 'med', 'high'];
   119	  var DEFAULT_PRIORITY = 'med';
   120	  var PRIORITY_LABELS = { low: 'Low', med: 'Med', high: 'High' };
   121	
   122	  function normalizePriority(p) {
   123	    return PRIORITIES.indexOf(p) !== -1 ? p : DEFAULT_PRIORITY;
   124	  }
   125	
   126	  function load() {
   127	    try {
   128	      var data = JSON.parse(localStorage.getItem(STORAGE_KEY));
   129	      if (!Array.isArray(data)) return [];
   130	      // Todos saved before priorities existed default to "med".
   131	      data.forEach(function (t) { t.priority = normalizePriority(t.priority); });
   132	      return data;
   133	    } catch (e) {
   134	      return [];
   135	    }
   136	  }
   137	
   138	  function save() {
   139	    try {
   140	      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
   141	    } catch (e) {
   142	      // Storage may be unavailable (e.g. blocked); the app still works in memory.
   143	    }
   144	  }
   145	
   146	  function makeId() {
   147	    if (window.crypto && typeof crypto.randomUUID === 'function') {
   148	      return crypto.randomUUID();
   149	    }
   150	    return Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);
   151	  }
   152	
   153	  // Date rule (project decision): a due date is a plain "YYYY-MM-DD" string
   154	  // meaning a LOCAL calendar date. Never pass it through Date parsing or UTC
   155	  // (new Date("YYYY-MM-DD") is UTC midnight). Compare as strings, date-only.
   156	  var DATE_RE = /^\d{4}-\d{2}-\d{2}$/;
   157	
   158	  function pad(n) { return (n < 10 ? '0' : '') + n; }
   159	
   160	  function todayLocal() {
   161	    var d = new Date();
   162	    return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());
   163	  }
   164	
   165	  // Overdue: due date strictly before today's local date. Due today is never overdue.
   166	  // Zero-padded YYYY-MM-DD strings sort the same as the dates they name.
   167	  function isOverdue(todo, today) {
   168	    return !!todo.due && todo.due < today;
   169	  }
   170	
   171	  function formatDue(due) {
   172	    var parts = due.split('-');
   173	    var local = new Date(+parts[0], +parts[1] - 1, +parts[2]);
   174	    return local.toLocaleDateString(undefined, { year: 'numeric', month: 'short', day: 'numeric' });
   175	  }
   176	
   177	  var todos = load();
   178	  var filter = 'all';
   179	  var query = '';
   180	  var renderedDay = null;
   181	  var editing = false;
   182	
   183	  // Ordering rule (project decision): active todos first, completed todos below.
   184	  // Within each group, sort by priority (high, med, low); within the same
   185	  // priority, keep insertion order (oldest first). `todos` is stored in
   186	  // insertion order, and the index tiebreak keeps the sort stable.
   187	  var PRIORITY_RANK = { high: 0, med: 1, low: 2 };
   188	
   189	  function byPriority(group) {
   190	    return group
   191	      .map(function (t, i) { return { todo: t, index: i }; })
   192	      .sort(function (a, b) {
   193	        return (PRIORITY_RANK[a.todo.priority] - PRIORITY_RANK[b.todo.priority]) || (a.index - b.index);
   194	      })
   195	      .map(function (entry) { return entry.todo; });
   196	  }
   197	
   198	  // Search: case-insensitive substring match on text, combined with the filter.
   199	  function matchesQuery(todo) {
   200	    return !query || todo.text.toLowerCase().indexOf(query) !== -1;
   201	  }
   202	
   203	  function visibleTodos() {
   204	    var matching = todos.filter(matchesQuery);
   205	    var active = byPriority(matching.filter(function (t) { return !t.completed; }));
   206	    var completed = byPriority(matching.filter(function (t) { return t.completed; }));
   207	    if (filter === 'active') return active;
   208	    if (filter === 'completed') return completed;
   209	    return active.concat(completed);
   210	  }
   211	
   212	  function render() {
   213	    list.textContent = '';
   214	    var visible = visibleTodos();
   215	    var today = todayLocal();
   216	    renderedDay = today;
   217	    visible.forEach(function (todo) {
   218	      var li = document.createElement('li');
   219	      li.setAttribute('data-testid', 'todo-item');
   220	      li.setAttribute('data-id', todo.id);
   221	      li.setAttribute('data-completed', todo.completed ? 'true' : 'false');
   222	      li.setAttribute('data-overdue', isOverdue(todo, today) ? 'true' : 'false');
   223	      li.setAttribute('data-priority', todo.priority);
   224	
   225	      var toggle = document.createElement('input');
   226	      toggle.type = 'checkbox';
   227	      toggle.checked = !!todo.completed;
   228	      toggle.setAttribute('data-testid', 'todo-toggle');
   229	      toggle.setAttribute('aria-label', 'Mark complete');
   230	      toggle.addEventListener('change', function () { setCompleted(todo.id, toggle.checked); });
   231	
   232	      var text = document.createElement('span');
   233	      text.className = 'text';
   234	      text.setAttribute('data-testid', 'todo-text');
   235	      text.textContent = todo.text;
   236	      text.addEventListener('dblclick', function () { startEdit(text, todo); });
   237	
   238	      var del = document.createElement('button');
   239	      del.type = 'button';
   240	      del.className = 'delete';
   241	      del.setAttribute('data-testid', 'todo-delete');
   242	      del.setAttribute('aria-label', 'Delete todo');
   243	      del.textContent = 'Delete';
   244	      del.addEventListener('click', function () { remove(todo.id); });
   245	
   246	      var priority = document.createElement('span');
   247	      priority.className = 'priority';
   248	      priority.setAttribute('data-testid', 'todo-priority-label');
   249	      priority.textContent = PRIORITY_LABELS[todo.priority];
   250	
   251	      li.appendChild(toggle);
   252	      li.appendChild(text);
   253	      li.appendChild(priority);
   254	      if (todo.due) {
   255	        var due = document.createElement('time');
   256	        due.className = 'due';
   257	        due.setAttribute('data-testid', 'todo-due-date');
   258	        due.setAttribute('datetime', todo.due);
   259	        due.textContent = 'Due ' + formatDue(todo.due);
   260	        li.appendChild(due);
   261	      }
   262	      li.appendChild(del);
   263	      list.appendChild(li);
   264	    });
   265	    empty.textContent = todos.length === 0 ? 'No todos yet.'
   266	      : query ? 'No todos match your search.'
   267	      : filter === 'active' ? 'No active todos.'
   268	      : 'No completed todos.';
   269	    empty.hidden = visible.length > 0;
   270	    filterButtons.forEach(function (btn) {
   271	      btn.setAttribute('aria-pressed', btn.getAttribute('data-filter') === filter ? 'true' : 'false');
   272	    });
   273	  }
   274	
   275	  function add(text, due, priority) {
   276	    todos.push({ id: makeId(), text: text, completed: false, createdAt: Date.now(), due: due, priority: normalizePriority(priority) });
   277	    save();
   278	    render();
   279	  }
   280	
   281	  // Inline editing: Enter or blur commits, Escape cancels.
   282	  // Empty text on commit keeps the original text.
   283	  function startEdit(textEl, todo) {
   284	    if (editing) return;
   285	    editing = true;
   286	    var field = document.createElement('input');
   287	    field.type = 'text';
   288	    field.className = 'edit';
   289	    field.setAttribute('data-testid', 'todo-edit-input');
   290	    field.setAttribute('aria-label', 'Edit todo');
   291	    field.value = todo.text;
   292	    var finished = false;
   293	
   294	    function finish(commit) {
   295	      if (finished) return;
   296	      finished = true;
   297	      editing = false;
   298	      var value = field.value.trim();
   299	      if (commit && value && value !== todo.text) {
   300	        todo.text = value;
   301	        save();
   302	      }
   303	      render();
   304	    }
   305	
   306	    field.addEventListener('keydown', function (e) {
   307	      if (e.key === 'Enter') { e.preventDefault(); finish(true); }
   308	      else if (e.key === 'Escape') { e.preventDefault(); finish(false); }
   309	    });
   310	    field.addEventListener('blur', function () { finish(true); });
   311	
   312	    textEl.replaceWith(field);
   313	    field.focus();
   314	    field.select();
   315	  }
   316	
   317	  function remove(id) {
   318	    todos = todos.filter(function (t) { return t.id !== id; });
   319	    save();
   320	    render();
   321	  }
   322	
   323	  function setCompleted(id, completed) {
   324	    todos.forEach(function (t) { if (t.id === id) t.completed = completed; });
   325	    save();
   326	    render();
   327	  }
   328	
   329	  // Bulk actions apply to every todo, ignoring the active filter and search.
   330	  // They only change `completed` or drop items; `todos` keeps insertion order,
   331	  // so render() still applies the agreed ordering rule.
   332	  function markAllComplete() {
   333	    todos.forEach(function (t) { t.completed = true; });
   334	    save();
   335	    render();
   336	  }
   337	
   338	  function clearCompleted() {
   339	    todos = todos.filter(function (t) { return !t.completed; });
   340	    save();
   341	    render();
   342	  }
   343	
   344	  markAllButton.addEventListener('click', markAllComplete);
   345	  clearCompletedButton.addEventListener('click', clearCompleted);
   346	
   347	  filterButtons.forEach(function (btn) {
   348	    btn.addEventListener('click', function () {
   349	      filter = btn.getAttribute('data-filter');
   350	      render();
   351	    });
   352	  });
   353	
   354	  searchInput.addEventListener('input', function () {
   355	    query = searchInput.value.trim().toLowerCase();
   356	    render();
   357	  });
   358	
   359	  form.addEventListener('submit', function (e) {
   360	    e.preventDefault();
   361	    var text = input.value.trim();
   362	    if (!text) return;
   363	    var due = DATE_RE.test(dueInput.value) ? dueInput.value : null;
   364	    add(text, due, priorityInput.value);
   365	    input.value = '';
   366	    dueInput.value = '';
   367	    priorityInput.value = DEFAULT_PRIORITY;
   368	    input.focus();
   369	  });
   370	
   371	  render();
   372	
   373	  // Overdue status changes at local midnight; re-render when the day rolls over.
   374	  setInterval(function () {
   375	    // Skip while editing so a re-render does not discard the edit.
   376	    if (!editing && todayLocal() !== renderedDay) render();
   377	  }, 30000);
   378	})();
   379	</script>
   380	</body>
   381	</html>
