const { chromium } = require('playwright');
const path = require('path');
const URL = 'file://' + path.resolve(process.argv[2]);

let failures = 0, passes = 0;
function check(name, cond, extra) {
  if (cond) { passes++; }
  else { failures++; console.log('FAIL:', name, extra !== undefined ? JSON.stringify(extra) : ''); }
}
const T = (id) => `[data-testid="${id}"]`;

async function newPage(browser, opts = {}) {
  const ctx = await browser.newContext({ timezoneId: opts.tz || 'America/Los_Angeles' });
  const page = await ctx.newPage();
  const errors = [];
  page.on('pageerror', (e) => errors.push(String(e)));
  if (opts.time) await page.clock.setFixedTime(opts.time);
  if (opts.storage) {
    await page.addInitScript((s) => {
      if (!sessionStorage.getItem('seeded')) { localStorage.setItem('todos', s); sessionStorage.setItem('seeded', '1'); }
    }, opts.storage);
  }
  await page.goto(URL);
  return { ctx, page, errors };
}
const texts = (page) => page.$$eval(T('todo-text'), (els) => els.map((e) => e.textContent));
async function addTodo(page, text, due, pri) {
  if (due) await page.fill(T('todo-due'), due);
  if (pri) await page.selectOption(T('todo-priority'), pri);
  await page.fill(T('todo-input'), text);
  await page.press(T('todo-input'), 'Enter');
}

(async () => {
  const browser = await chromium.launch();

  // --- Add: Enter, button, trim, empty ignored, reset of fields, focus ---
  {
    const { ctx, page, errors } = await newPage(browser);
    await page.fill(T('todo-input'), '  first  ');
    await page.press(T('todo-input'), 'Enter');
    check('enter adds', (await texts(page)).join() === 'first', await texts(page));
    check('input cleared', (await page.inputValue(T('todo-input'))) === '');
    check('input keeps focus', await page.evaluate(() => document.activeElement.dataset.testid === 'todo-input'));
    await page.fill(T('todo-input'), 'second');
    await page.click(T('todo-add'));
    check('button adds', (await texts(page)).join() === 'first,second');
    await page.fill(T('todo-input'), '   ');
    await page.press(T('todo-input'), 'Enter');
    check('blank ignored', (await texts(page)).length === 2);
    await page.selectOption(T('todo-priority'), 'high');
    await page.fill(T('todo-due'), '2030-01-01');
    await addTodo(page, 'third');
    check('priority reset to med', (await page.inputValue(T('todo-priority'))) === 'med');
    check('due reset', (await page.inputValue(T('todo-due'))) === '');
    // "/" typed in the todo input is text, not a shortcut
    await page.fill(T('todo-input'), '');
    await page.type(T('todo-input'), 'a/b');
    check('slash types in todo input', (await page.inputValue(T('todo-input'))) === 'a/b');
    check('focus stays in todo input', await page.evaluate(() => document.activeElement.dataset.testid === 'todo-input'));
    check('no errors', errors.length === 0, errors);
    await ctx.close();
  }

  // --- "/" shortcut ---
  {
    const { ctx, page, errors } = await newPage(browser);
    await addTodo(page, 'alpha');
    await page.evaluate(() => document.activeElement.blur());
    await page.keyboard.press('/');
    check('slash focuses search', await page.evaluate(() => document.activeElement.dataset.testid === 'search-input'));
    check('slash not typed into search', (await page.inputValue(T('search-input'))) === '');
    await page.keyboard.type('x/y');
    check('slash types in search', (await page.inputValue(T('search-input'))) === 'x/y');
    // from a button
    await page.click(T('filter-active'));
    await page.keyboard.press('/');
    check('slash from button focuses search', await page.evaluate(() => document.activeElement.dataset.testid === 'search-input'));
    // ignored in date / select / edit field
    await page.focus(T('todo-priority'));
    await page.keyboard.press('/');
    check('slash ignored in select', await page.evaluate(() => document.activeElement.dataset.testid === 'todo-priority'));
    await page.fill(T('search-input'), '');
    await page.dblclick(T('todo-text'));
    await page.keyboard.press('End');
    await page.keyboard.type('/z');
    check('slash types in edit field', (await page.inputValue(T('todo-edit-input'))) === 'alpha/z');
    await page.keyboard.press('Enter');
    check('edit committed with slash', (await texts(page)).join() === 'alpha/z');
    // modifier combos ignored
    await page.evaluate(() => document.activeElement.blur());
    await page.keyboard.press('Control+/');
    check('ctrl+/ ignored', await page.evaluate(() => document.activeElement === document.body));
    check('no errors', errors.length === 0, errors);
    await ctx.close();
  }

  // --- Inline editing ---
  {
    const { ctx, page, errors } = await newPage(browser);
    await addTodo(page, 'one');
    await addTodo(page, 'two');
    await page.dblclick(`${T('todo-item')}:nth-child(1) ${T('todo-text')}`);
    check('edit input shown', (await page.$$(T('todo-edit-input'))).length === 1);
    await page.fill(T('todo-edit-input'), 'uno');
    await page.keyboard.press('Escape');
    check('escape cancels', (await texts(page)).join() === 'one,two' && (await page.$$(T('todo-edit-input'))).length === 0);
    await page.dblclick(`${T('todo-item')}:nth-child(1) ${T('todo-text')}`);
    await page.fill(T('todo-edit-input'), '  uno  ');
    await page.keyboard.press('Enter');
    check('enter commits trimmed', (await texts(page)).join() === 'uno,two');
    await page.dblclick(`${T('todo-item')}:nth-child(2) ${T('todo-text')}`);
    await page.fill(T('todo-edit-input'), 'dos');
    await page.click('h1');
    check('blur commits', (await texts(page)).join() === 'uno,dos');
    await page.dblclick(`${T('todo-item')}:nth-child(2) ${T('todo-text')}`);
    await page.fill(T('todo-edit-input'), '   ');
    await page.keyboard.press('Enter');
    check('empty keeps original', (await texts(page)).join() === 'uno,dos');
    // Escape must not add or change the new-todo input
    await page.fill(T('todo-input'), 'draft');
    await page.dblclick(`${T('todo-item')}:nth-child(1) ${T('todo-text')}`);
    await page.keyboard.press('Escape');
    check('escape leaves draft', (await page.inputValue(T('todo-input'))) === 'draft' && (await texts(page)).length === 2);
    await page.reload();
    check('edit persisted', (await texts(page)).join() === 'uno,dos');
    check('no errors', errors.length === 0, errors);
    await ctx.close();
  }

  // --- Ordering, priority, filters, search, bulk, delete, persistence ---
  {
    const { ctx, page, errors } = await newPage(browser);
    await addTodo(page, 'low-a', null, 'low');
    await addTodo(page, 'med-a');
    await addTodo(page, 'high-a', null, 'high');
    await addTodo(page, 'med-b', null, 'med');
    await addTodo(page, 'high-b', null, 'high');
    check('priority order', (await texts(page)).join() === 'high-a,high-b,med-a,med-b,low-a', await texts(page));
    // complete high-a -> goes below all active
    await page.click(`${T('todo-item')}:nth-child(1) ${T('todo-toggle')}`);
    check('completed below', (await texts(page)).join() === 'high-b,med-a,med-b,low-a,high-a', await texts(page));
    await page.click(`${T('todo-item')}:has-text("low-a") ${T('todo-toggle')}`);
    check('completed group sorted by priority', (await texts(page)).join() === 'high-b,med-a,med-b,high-a,low-a', await texts(page));
    // no priority tint
    const styles = await page.$$eval(T('todo-item'), (els) => els.filter((e) => e.dataset.completed === 'false').map((e) => {
      const cs = getComputedStyle(e); const lab = getComputedStyle(e.querySelector('.priority'));
      return [cs.backgroundColor, cs.borderColor, lab.backgroundColor, lab.color].join('|');
    }));
    check('no priority colour', new Set(styles).size === 1, styles);
    // filters
    await page.click(T('filter-active'));
    check('active filter', (await texts(page)).join() === 'high-b,med-a,med-b');
    check('aria-pressed', (await page.getAttribute(T('filter-active'), 'aria-pressed')) === 'true' && (await page.getAttribute(T('filter-all'), 'aria-pressed')) === 'false');
    await page.click(T('filter-completed'));
    check('completed filter', (await texts(page)).join() === 'high-a,low-a');
    // search combined with filter
    await page.fill(T('search-input'), '  HIGH ');
    check('search + completed filter', (await texts(page)).join() === 'high-a');
    await page.click(T('filter-all'));
